using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Non-static class — HttpClient and ILogger are injected via constructor DI.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a post by its numeric ID.")]
    public async Task<string> GetPost(
        [Description("The post ID (1–100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var post = await httpClient.GetFromJsonAsync<Post>(
            $"/posts/{id}", cancellationToken);
        return JsonSerializer.Serialize(post, JsonCtx.Default.Post);
    }

    [McpServerTool, Description("Search posts by user ID.")]
    public async Task<string> GetPostsByUser(
        [Description("The user ID to filter posts by")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching posts for user {UserId}", userId);
        var posts = await httpClient.GetFromJsonAsync<List<Post>>(
            $"/posts?userId={userId}", cancellationToken);
        return JsonSerializer.Serialize(posts, JsonCtx.Default.ListPost);
    }

    [McpServerTool, Description("Get all comments on a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to get comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching comments for post {PostId}", postId);
        var comments = await httpClient.GetFromJsonAsync<List<Comment>>(
            $"/posts/{postId}/comments", cancellationToken);
        return JsonSerializer.Serialize(comments, JsonCtx.Default.ListComment);
    }
}

// DTOs
public record Post(
    [property: JsonPropertyName("userId")] int UserId,
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("body")] string Body);

public record Comment(
    [property: JsonPropertyName("postId")] int PostId,
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("email")] string Email,
    [property: JsonPropertyName("body")] string Body);

// Source-generated JSON context for AOT compatibility
[JsonSerializable(typeof(Post))]
[JsonSerializable(typeof(List<Post>))]
[JsonSerializable(typeof(Comment))]
[JsonSerializable(typeof(List<Comment>))]
internal partial class JsonCtx : JsonSerializerContext;

